/**
 * Substitutes variables in the value of the given property name.
 */
public static String substVars(String propValue, Properties props) {
    // Find all occurrences of "${" and "}" in the value
    int startIndex = propValue.indexOf("${");
    if (startIndex == -1) {
        return propValue;
    }

    int endIndex = propValue.indexOf("}", startIndex);
    if (endIndex == -1) {
        return propValue;
    }

    // Extract the variable name
    String varName = propValue.substring(startIndex + 2, endIndex);

    // Find the value for the variable in the properties
    String varValue = props.getProperty(varName);
    if (varValue == null) {
        // No value found, leave the variable as is
        return propValue;
    }

    // Replace the variable with its value in the property value
    String replacedValue = propValue.substring(0, startIndex) + varValue + propValue.substring(endIndex + 1);

    // Recursively substitute variables in the replaced value
    return substVars(replacedValue, props);
}

